def load() -> pd.DataFrame:
    df = pd.read_csv('data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Count.csv', skiprows=2)
    df = df.dropna(how='all')
    df['Year'] = pd.to_numeric(df['Year'], errors='coerce')
    df['# of Reports'] = df['# of Reports'].str.replace(',', '').astype(float)
    return df.dropna()

def process(load_report_count) -> pd.DataFrame:
    df_2007 = load_report_count[load_report_count['Year'] == 2007]
    return df_2007

def process(extract_2024_distribution) -> pd.DataFrame:
